@Twig_the_Blue_Pikmin
try this as a plugin below the party system one and should consume the actor's turn.
Code:
(() => {
Scene_Party.prototype.commandFinish = function() {
    if ($gameParty.inBattle()) {
      $gameParty.reconstructActions();
      if (BattleManager._savedActor) {
        BattleManager._actorIndex = BattleManager._savedActor.index();
        BattleManager.startATBAction(BattleManager._savedActor);
      }
    }
    this.popScene();
};
})();

